    #[tokio::test]
    async fn plugin_rejection_response_runs_security_headers() {
        let plugins: Vec<Arc<dyn Plugin>> =
            vec![Arc::new(SecurityHeaders::new(&json!({})).unwrap())];
        let mut ctx = RequestContext::new("203.0.113.10".into(), "GET".into(), "/body".into());
        let mut response_status = 200;
        let mut response_headers = HashMap::new();
        let reject = RejectedResponseParts {
            status_code: 403,
            body: br#"{"error":"blocked"}"#.to_vec(),
            headers: HashMap::new(),
        };

        let body = apply_plugin_rejection_response(
            &plugins,
            &mut ctx,
            &mut response_status,
            &mut response_headers,
            reject,
        )
        .await;

        assert_eq!(response_status, 403);
        assert_eq!(
            response_headers
                .get("x-content-type-options")
                .map(String::as_str),
            Some("nosniff")
        );
        assert_eq!(
            response_headers.get("x-frame-options").map(String::as_str),
            Some("SAMEORIGIN")
        );
        assert_eq!(body, br#"{"error":"blocked"}"#);
    }

    #[tokio::test]
    async fn grpc_plugin_rejection_response_runs_security_headers() {
        let plugins: Vec<Arc<dyn Plugin>> =
            vec![Arc::new(SecurityHeaders::new(&json!({})).unwrap())];
        let mut ctx = RequestContext::new(
            "203.0.113.10".into(),
            "POST".into(),
            "/grpc.Service/Method".into(),
        );
        let reject = RejectedResponseParts {
            status_code: 403,
            body: br#"{"error":"Forbidden"}"#.to_vec(),
            headers: HashMap::new(),
        };

        let normalized =
            normalize_grpc_plugin_rejection_with_after_proxy_hooks(&plugins, &mut ctx, reject)
                .await;

        assert_eq!(normalized.http_status, StatusCode::OK);
        assert_eq!(
            normalized.grpc_status,
            Some(grpc_proxy::grpc_status::PERMISSION_DENIED)
        );
        assert_eq!(
            normalized
                .headers
                .get("x-content-type-options")
                .map(String::as_str),
            Some("nosniff")
        );
        assert_eq!(
            normalized
                .headers
                .get("x-frame-options")
                .map(String::as_str),
            Some("SAMEORIGIN")
        );
    }

    #[test]
    fn backend_tls_watched_sources_collects_and_deduplicates_sources() {
        let env_config = EnvConfig {
            tls_ca_bundle_path: Some("/ca/global.pem".to_string()),
            backend_tls_client_cert_path: Some("/certs/shared.pem".to_string()),
            backend_tls_client_key_path: Some("/keys/global.key".to_string()),
            tls_crl_file_path: Some("/crl/global.pem".to_string()),
            ..EnvConfig::default()
        };
        let mut config: GatewayConfig = serde_json::from_value(json!({
            "version": "1",
            "proxies": [{
                "id": "p1",
                "listen_path": "/",
                "backend_host": "api.example.com",
                "backend_port": 443,
                "backend_scheme": "https"
            }],
            "consumers": [],
            "plugin_configs": [{
                "id": "mrd1",
                "plugin_name": "mesh_route_dispatch",
                "scope": "proxy",
                "proxy_id": "p1",
                "enabled": true,
                "config": {
                    "rules": [{
                        "match": {"methods": ["GET"]},
                        "destination": {
                            "backend_host": "canary.example.com",
                            "backend_port": 443,
                            "backend_tls": {
                                "client_cert_path": "/certs/mesh-route.pem",
                                "client_key_path": "/keys/mesh-route.key",
                                "server_ca_cert_path": "/ca/mesh-route.pem"
                            }
                        }
                    }]
                }
            }],
            "upstreams": [{
                "id": "u1",
                "targets": [{"host": "api.example.com", "port": 443}],
                "backend_tls_client_cert_path": "/certs/shared.pem",
                "backend_tls_client_key_path": "/keys/upstream.key",
                "backend_tls_server_ca_cert_path": "/ca/upstream.pem"
            }]
        }))
        .expect("config should deserialize");
        config.proxies[0].resolved_tls = BackendTlsConfig {
            client_cert_path: Some("/certs/proxy.pem".to_string()),
            client_key_path: Some("/keys/proxy.key".to_string()),
            server_ca_cert_path: Some("/ca/proxy.pem".to_string()),
            verify_server_cert: true,
            sni: None,
            san_allow_list: Vec::new(),
            san_allow_list_key_digest: None,
        };

        let sources = collect_backend_tls_watched_sources(&config, &env_config);
        let ids = sources
            .iter()
            .map(|source| source.source.pool_key_component())
            .collect::<Vec<_>>();

        assert_eq!(sources.len(), 12);
        assert_eq!(
            ids.iter()
                .filter(|id| id.as_str() == "/certs/shared.pem")
                .count(),
            1,
            "shared global/upstream cert source should be watched once"
        );
        assert!(ids.contains(&"/ca/global.pem".to_string()));
        assert!(ids.contains(&"/crl/global.pem".to_string()));
        assert!(ids.contains(&"/ca/proxy.pem".to_string()));
        assert!(ids.contains(&"/ca/upstream.pem".to_string()));
        assert!(ids.contains(&"/certs/mesh-route.pem".to_string()));
        assert!(ids.contains(&"/keys/mesh-route.key".to_string()));
        assert!(ids.contains(&"/ca/mesh-route.pem".to_string()));
    }

    #[test]
    fn clone_log_metadata_removes_body_and_unowned_waf_metadata() {
        let mut ctx = RequestContext::new("203.0.113.10".into(), "GET".into(), "/search".into());
        ctx.metadata
            .insert("request_body".to_string(), "secret body".to_string());
        ctx.metadata
            .insert("waf.rule_hits".to_string(), "SPOOFED".to_string());
        ctx.metadata
            .insert("waf.action".to_string(), "blocked".to_string());

        let metadata = clone_log_metadata(&ctx);

        assert!(!metadata.contains_key("request_body"));
        assert!(!metadata.contains_key("waf.rule_hits"));
        assert!(!metadata.contains_key("waf.action"));

        ctx.set_waf_metadata("waf.rule_hits", "FE-SQLI-001");
        ctx.metadata
            .insert("waf.action".to_string(), "blocked".to_string());

        let metadata = clone_log_metadata(&ctx);

        assert_eq!(
            metadata.get("waf.rule_hits").map(String::as_str),
            Some("FE-SQLI-001")
        );
        assert!(!metadata.contains_key("waf.action"));
    }

