    /// End-to-end wiring guard for the content-type-aware buffer->stream
    /// downgrade: drives `proxy_to_backend` against a real backend with a
    /// response-inspecting WAF and asserts a non-inspectable (binary) response
    /// is streamed (downgraded) while an allowlisted (json) one stays buffered.
    /// A refactor that drops the `refine_stream_response_for_content_type` call
    /// site would regress the binary case back to `Buffered` and fail here —
    /// which the helper-level unit tests cannot catch.
    #[tokio::test]
    async fn proxy_to_backend_downgrades_non_inspectable_response_under_waf_inspection() {
        async fn dispatch_body(
            state: &ProxyState,
            proxy: &Proxy,
            plugins: &[Arc<dyn Plugin>],
            backend_url: &str,
        ) -> ResponseBody {
            let ctx = RequestContext::new("127.0.0.1".into(), "GET".into(), "/".into());
            let bytes_sent = Arc::new(std::sync::atomic::AtomicU64::new(0));
            let dispatch = proxy_to_backend(
                state,
                proxy,
                backend_url,
                "GET",
                &HashMap::new(),
                ClientRequestBody::Buffered(Vec::new()),
                None,
                plugins,
                &[],
                None,  // body-hook ctx (absent for response-only configs)
                &ctx,  // real read-only request context
                false, // stream_response: WAF requested buffering pre-flight
                false, // requires_request_body_buffering
                true,  // stream_request_body
                false, // retain_request_body (non-retry -> downgrade active)
                "127.0.0.1",
                "127.0.0.1",
                false, // is_tls
                false, // dispatch_hbone
                false, // dispatch_mesh_mtls
                false, // dispatch_h3
                &bytes_sent,
                hyper::Version::HTTP_11,
                &mut std::time::Instant::now(),
            )
            .await;
            let resp = match dispatch {
                BackendDispatchResult::Response { response, .. } => response,
                BackendDispatchResult::AdmissionRejected(_) => {
                    panic!("test does not configure backend admission plugins")
                }
            };
            resp.body
        }

        let server = wiremock::MockServer::start().await;
        // 128 KiB > the 64 KiB eager-buffer cutoff, so a downgraded response
        // actually streams instead of being eagerly collected as a small body.
        wiremock::Mock::given(wiremock::matchers::path("/binary"))
            .respond_with(
                wiremock::ResponseTemplate::new(200)
                    .insert_header("content-type", "application/octet-stream")
                    .set_body_bytes(vec![0u8; 131_072]),
            )
            .mount(&server)
            .await;
        wiremock::Mock::given(wiremock::matchers::path("/json"))
            .respond_with(
                wiremock::ResponseTemplate::new(200)
                    .insert_header("content-type", "application/json")
                    .set_body_bytes(vec![b' '; 131_072]),
            )
            .mount(&server)
            .await;

        let state = make_test_proxy_state(GatewayConfig::default());
        let mut proxy = test_proxy(ResponseBodyMode::Stream);
        proxy.backend_scheme = Some(BackendScheme::Http);
        proxy.backend_host = server.address().ip().to_string();
        proxy.backend_port = server.address().port();

        let plugins: Vec<Arc<dyn Plugin>> = vec![Arc::new(
            crate::plugins::waf::Waf::new(&json!({
                "response_inspection": true,
                "response_body_inspection": true,
            }))
            .unwrap(),
        )];

        let binary = dispatch_body(
            &state,
            &proxy,
            &plugins,
            &format!("{}/binary", server.uri()),
        )
        .await;
        assert!(
            matches!(binary, ResponseBody::Streaming { .. }),
            "non-inspectable (octet-stream) response should be downgraded to streaming"
        );

        let json_body =
            dispatch_body(&state, &proxy, &plugins, &format!("{}/json", server.uri())).await;
        assert!(
            matches!(json_body, ResponseBody::Buffered(_)),
            "allowlisted (json) response must stay buffered so the WAF can scan it"
        );
    }

    #[tokio::test]
    async fn h1_to_native_h3_backend_headers_preserve_frontend_forwarding_metadata() {
        let env_config = crate::config::env_config::EnvConfig {
            add_via_header: true,
            add_forwarded_header: true,
            ..Default::default()
        };
        let state = make_test_proxy_state_with_env(GatewayConfig::default(), env_config);
        let mut proxy = test_proxy(ResponseBodyMode::Stream);
        proxy.backend_scheme = Some(BackendScheme::Https);
        proxy.backend_host = "template.example".to_string();
        proxy.preserve_host_header = false;

        let headers = HashMap::from([
            ("host".to_string(), "edge.example".to_string()),
            ("connection".to_string(), "x-strip".to_string()),
            ("x-strip".to_string(), "leak".to_string()),
            ("x-keep".to_string(), "ok".to_string()),
            ("x-forwarded-for".to_string(), "198.51.100.7".to_string()),
        ]);

        let out = build_http3_backend_headers(
            &state,
            &proxy,
            &headers,
            Http3BackendHeaderContext {
                client_ip: "203.0.113.44",
                xff_append_ip: "127.0.0.1",
                effective_host: "backend.internal",
                is_tls: false,
                inbound_version: hyper::Version::HTTP_11,
                content_length: None,
            },
        );

        assert_eq!(header_value(&out, "host"), Some("backend.internal"));
        assert_eq!(header_value(&out, "x-keep"), Some("ok"));
        // The resolved client (203.0.113.44) is absent from the inbound
        // chain, so the builder seeds it before the immediate peer — same
        // real-IP-header semantics as build_xff_value's truth table.
        assert_eq!(
            header_value(&out, "x-forwarded-for"),
            Some("198.51.100.7, 203.0.113.44, 127.0.0.1")
        );
        assert_eq!(header_value(&out, "x-forwarded-proto"), Some("http"));
        assert_eq!(header_value(&out, "x-forwarded-host"), Some("edge.example"));
        assert_eq!(header_value(&out, "via"), Some("1.1 ferrum-edge"));
        assert_eq!(
            header_value(&out, "forwarded"),
            Some("for=203.0.113.44;proto=http;host=edge.example")
        );
        assert!(
            header_value(&out, "x-strip").is_none(),
            "headers named by Connection must not be forwarded to H3 backends"
        );
    }

    #[tokio::test]
    async fn h2_tls_to_native_h3_backend_headers_use_h2_via_and_https_proto() {
        let env_config = crate::config::env_config::EnvConfig {
            add_via_header: true,
            add_forwarded_header: true,
            ..Default::default()
        };
        let state = make_test_proxy_state_with_env(GatewayConfig::default(), env_config);
        let mut proxy = test_proxy(ResponseBodyMode::Stream);
        proxy.backend_scheme = Some(BackendScheme::Https);

        let headers = HashMap::from([("host".to_string(), "api.example".to_string())]);
        let out = build_http3_backend_headers(
            &state,
            &proxy,
            &headers,
            Http3BackendHeaderContext {
                client_ip: "203.0.113.9",
                xff_append_ip: "10.0.0.7",
                effective_host: "h3-backend.example",
                is_tls: true,
                inbound_version: hyper::Version::HTTP_2,
                content_length: None,
            },
        );

        assert_eq!(header_value(&out, "x-forwarded-proto"), Some("https"));
        // No inbound XFF and resolved client != peer (real-IP-header
        // deployment): the generated chain seeds the resolved client
        // before the immediate peer.
        assert_eq!(
            header_value(&out, "x-forwarded-for"),
            Some("203.0.113.9, 10.0.0.7")
        );
        assert_eq!(header_value(&out, "via"), Some("2.0 ferrum-edge"));
        assert_eq!(
            header_value(&out, "forwarded"),
            Some("for=203.0.113.9;proto=https;host=api.example")
        );
    }

