    // ----- Per-IP cleanup task shutdown wiring ---------------------------
    //
    // The cleanup loop must honour the global shutdown watch channel so the
    // spawned task can be drained during the 5 s background-task drain phase
    // (mirrors DNS / overload / metrics handles). Before this wiring the task
    // ran an unbounded `loop { timer.tick().await; ... }` and the handle was
    // dropped on the floor, so shutdown couldn't await it. Regression test:
    // signalling the channel must end the task within a tight grace window.

    #[tokio::test]
    async fn per_ip_cleanup_loop_exits_when_shutdown_signal_fires() {
        let counts: Arc<dashmap::DashMap<String, AtomicU64>> = Arc::new(dashmap::DashMap::new());
        let (tx, rx) = tokio::sync::watch::channel(false);

        // Use a long interval so the test latency is dominated by the
        // shutdown branch of the `tokio::select!`, not by `timer.tick()`.
        let handle = tokio::spawn(run_per_ip_cleanup_loop(counts.clone(), 3600, Some(rx)));

        tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        assert!(
            !handle.is_finished(),
            "task should still be running before shutdown is signalled"
        );

        tx.send(true).expect("watch receiver should still be live");
        let result = tokio::time::timeout(std::time::Duration::from_secs(2), handle).await;
        assert!(
            matches!(result, Ok(Ok(()))),
            "task should exit within 2s of shutdown signal; got {result:?}"
        );
    }

    // Sanity: a `None` shutdown receiver leaves the loop running indefinitely.
    // Shutdown wiring remains opt-in via `Some`.
    #[tokio::test]
    async fn per_ip_cleanup_loop_runs_without_shutdown_receiver() {
        let counts: Arc<dashmap::DashMap<String, AtomicU64>> = Arc::new(dashmap::DashMap::new());
        let handle = tokio::spawn(run_per_ip_cleanup_loop(counts, 3600, None));

        tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        assert!(
            !handle.is_finished(),
            "task without shutdown receiver should keep ticking"
        );
        handle.abort();
    }

    // ── update_config / validate_full_config: validate-before-swap contract ──
    //
    // These tests pin down the canonical "validate fully BEFORE swap"
    // guard inside `update_config`. Existing call sites (file_loader,
    // db_loader, dp_client) all pre-validate, but the swap function MUST
    // also reject malformed configs so a future caller (e.g. an admin
    // "import config" handler that deserializes JSON straight into
    // `update_config`) cannot publish an invalid config to the hot path.
    //
    // See `validate_full_config()` rustdoc for the warn-vs-reject
    // categorization and rationale.

    fn make_test_proxy_state(initial_config: GatewayConfig) -> ProxyState {
        make_test_proxy_state_with_env(
            initial_config,
            crate::config::env_config::EnvConfig::default(),
        )
    }

    fn make_test_proxy_state_with_env(
        initial_config: GatewayConfig,
        env_config: crate::config::env_config::EnvConfig,
    ) -> ProxyState {
        let reserved_gateway_ports = env_config.reserved_gateway_ports();
        make_test_proxy_state_with_reserved_ports(
            initial_config,
            env_config,
            reserved_gateway_ports,
        )
    }

    fn make_test_proxy_state_with_reserved_ports(
        initial_config: GatewayConfig,
        env_config: crate::config::env_config::EnvConfig,
        reserved_gateway_ports: HashSet<u16>,
    ) -> ProxyState {
        let dns_cache = crate::dns::DnsCache::new(crate::dns::DnsConfig::default());
        ProxyState::new_with_reserved_gateway_ports(
            initial_config,
            dns_cache,
            env_config,
            None,
            None,
            reserved_gateway_ports,
        )
        .expect("ProxyState construction should succeed in tests")
        .0
    }

    fn header_value<'a>(
        headers: &'a [(hyper::header::HeaderName, hyper::header::HeaderValue)],
        name: &str,
    ) -> Option<&'a str> {
        headers.iter().find_map(|(header_name, value)| {
            header_name
                .as_str()
                .eq_ignore_ascii_case(name)
                .then(|| value.to_str().ok())
                .flatten()
        })
    }

    #[tokio::test]
    async fn backend_svid_rotation_channel_updates_pool_generation() {
        let state = make_test_proxy_state(GatewayConfig::default());
        assert_eq!(state.backend_svid_generation.load(Ordering::Acquire), 0);

        state.backend_svid_rotation_tx.send_replace(7);

        tokio::time::timeout(Duration::from_secs(1), async {
            loop {
                if state.backend_svid_generation.load(Ordering::Acquire) == 7 {
                    break;
                }
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("backend SVID generation should update");
    }

    fn make_validation_proxy(id: &str, listen_path: &str) -> Proxy {
        serde_json::from_value(json!({
            "id": id,
            "namespace": "ferrum",
            "name": "test-proxy",
            "hosts": [],
            "listen_path": listen_path,
            "backend_scheme": "http",
            "backend_host": "backend.example.com",
            "backend_port": 8080,
            "strip_listen_path": true,
            "preserve_host_header": false,
            "backend_connect_timeout_ms": 5000,
            "backend_read_timeout_ms": 30000,
            "backend_write_timeout_ms": 30000,
            "backend_tls_verify_server_cert": true,
        }))
        .expect("validation test proxy should deserialize")
    }

    fn make_validation_stream_proxy(id: &str, listen_port: u16) -> Proxy {
        let mut proxy: Proxy = serde_json::from_value(json!({
            "id": id,
            "namespace": "ferrum",
            "name": "test-stream-proxy",
            "listen_port": listen_port,
            "backend_scheme": "tcp",
            "backend_host": "backend.example.com",
            "backend_port": 8080,
            "backend_tls_verify_server_cert": true,
        }))
        .expect("validation test stream proxy should deserialize");
        proxy.normalize_fields();
        proxy
    }

    fn make_validation_config(proxies: Vec<Proxy>) -> GatewayConfig {
        GatewayConfig {
            version: "1".to_string(),
            proxies,
            consumers: vec![],
            plugin_configs: vec![],
            upstreams: vec![],
            loaded_at: chrono::Utc::now(),
            known_namespaces: Vec::new(),
            frontend_tls_cert_path: None,
            frontend_tls_key_path: None,
            frontend_tls_source_namespace: None,
            frontend_tls_namespace_sources: Vec::new(),
            trust_bundles: None,
            mesh: None,
        }
    }

    #[test]
    fn websocket_idle_disabled_collector_filters_http_family_zero_effective() {
        let mut disabled = make_validation_proxy("disabled", "/a");
        disabled.websocket_idle_timeout_seconds = Some(0);
        let mut bounded = make_validation_proxy("bounded", "/b");
        bounded.websocket_idle_timeout_seconds = Some(120);
        let mut inherit = make_validation_proxy("inherit", "/c");
        inherit.websocket_idle_timeout_seconds = None; // inherits the global value

        let mut config = make_validation_config(vec![disabled, bounded, inherit]);
        // Resolve `dispatch_kind` exactly as `update_config` does before the
        // collector runs in `mirror_request_epoch_wrappers`.
        config.normalize_fields();

        // Global bounded (300): only the explicit `Some(0)` override is disabled.
        assert_eq!(
            websocket_idle_disabled_proxy_ids(&config, 300),
            vec!["disabled"]
        );

        // Global disabled (0): the `Some(0)` override AND the inheriting proxy
        // are disabled; the explicit `Some(120)` override stays bounded.
        let mut ids = websocket_idle_disabled_proxy_ids(&config, 0);
        ids.sort();
        assert_eq!(ids, vec!["disabled", "inherit"]);
    }

    #[test]
    fn websocket_idle_newly_disabled_reports_only_transitions() {
        let mut prev_a = make_validation_proxy("a", "/a");
        prev_a.websocket_idle_timeout_seconds = Some(0); // already disabled
        let prev_b = make_validation_proxy("b", "/b"); // bounded (inherits global)
        let mut previous = make_validation_config(vec![prev_a, prev_b]);
        previous.normalize_fields();

        let mut next_a = make_validation_proxy("a", "/a");
        next_a.websocket_idle_timeout_seconds = Some(0); // still disabled
        let mut next_b = make_validation_proxy("b", "/b");
        next_b.websocket_idle_timeout_seconds = Some(0); // newly disabled
        let mut next_c = make_validation_proxy("c", "/c");
        next_c.websocket_idle_timeout_seconds = Some(0); // added, disabled
        let mut next = make_validation_config(vec![next_a, next_b, next_c]);
        next.normalize_fields();

        // "a" was already disabled -> excluded; only the transitions report.
        let mut newly = websocket_idle_newly_disabled_proxy_ids(&previous, &next, 300);
        newly.sort();
        assert_eq!(newly, vec!["b", "c"]);

        // Steady state (no new transitions) reports nothing, so a persistent
        // opt-out does not re-warn on every unrelated reload.
        assert!(websocket_idle_newly_disabled_proxy_ids(&next, &next, 300).is_empty());
    }

